from typing import List
def separate_paren_groups(paren_string: str) -> List[str]:
    processed = paren_string.replace(" ", "")
    result = []
    current_start = 0
    balance = 0
    for i, c in enumerate(processed):
        if c == '(':
            balance += 1
        else:
            balance -= 1
        if balance == 0:
            result.append(processed[current_start:i+1])
            current_start = i + 1
    return result

