def count_up_to(n):
    """Return an array of all prime numbers less than n."""
    if n < 2:
        return []
    sieve = [True] * n
    sieve[0], sieve[1] = False, False
    for i in range(2, int(n ** 0.5) + 1):
        if sieve[i]:
            sieve[i*i : n : i] = [False] * len(sieve[i*i : n : i])
    return [i for i, is_prime in enumerate(sieve) if is_prime]

