def tri(n):
    if n == 0:
        return [1]

    # Determine the maximum index needed
    if n % 2 == 0:
        max_index = n
    else:
        max_index = n + 1

    # Initialize the list with zeros
    tri_list = [0] * (max_index + 1)
    tri_list[0] = 1
    tri_list[1] = 3

    # Fill even terms
    for i in range(2, max_index + 1, 2):
        tri_list[i] = 1 + i // 2

    # Fill odd terms
    for i in range(3, max_index + 1, 2):
        tri_list[i] = tri_list[i - 1] + tri_list[i - 2] + tri_list[i + 1]

    return tri_list[:n + 1]
